/**
 * emit to subscription queries of type FindPharmacy,
 * but only if the id matches
 *
 * @param		entity	Pharmacy
 */
	protected void emitFindPharmacy( Pharmacy entity ) {
		LOGGER.info("handling emitFindPharmacy" );
		
	    queryUpdateEmitter.emit(FindPharmacyQuery.class,
	                            query -> query.getFilter().getPharmacyId().equals(entity.getPharmacyId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllPharmacy
	 * 
	 * @param		entity	Pharmacy
	 */
	protected void emitFindAllPharmacy( Pharmacy entity ) {
		LOGGER.info("handling emitFindAllPharmacy" );
		
	    queryUpdateEmitter.emit(FindAllPharmacyQuery.class,
	                            query -> true,
	                            entity);
	}

